insert into public.restaurants (id,slug,name,tagline,description,logo_url,hero_image_url,phone,address_line1,city,state,postal_code,timezone,theme_preset,currency,is_active,is_indexable,theme_overrides,primary_domain,pickup_url,doordash_url,google_maps_url,instagram_url,facebook_url,latitude,longitude) values
('20000000-0000-4000-8000-000000000001','super-tacos','Super Tacos','Bright salsas. Bold taco flavor.','Fresh tortillas, flame-grilled favorites, and house salsas bring a little sunshine to every bite. Find your new favorite, make it your own, and enjoy the good stuff.','/img/super-tacos/approved/supertacologo.svg','/img/super-tacos/approved/carnitas-tacos.webp','(951) 555-0147','0000 Magnolia Avenue','Riverside','CA','92503','America/Los_Angeles','classic-red','USD',true,false,'{"primary":"#163b32","accent":"#b53f1a","background":"#fff8e8","surface":"#ffffff","text":"#17352b","mutedText":"#526257","borderRadius":"18px"}',null,null,null,null,null,null,null,null);
