insert into public.menu_sections (id,menu_id,name,description,sort_order,is_active) values
('20000000-0000-4000-8000-000000000101','20000000-0000-4000-8000-000000000002','Street Tacos','Corn tortillas, bright salsa, and big flavor. Priced per taco.',0,true),
('20000000-0000-4000-8000-000000000102','20000000-0000-4000-8000-000000000002','Burritos','Wrapped warm and made your way. Add a little extra if you like.',1,true),
('20000000-0000-4000-8000-000000000103','20000000-0000-4000-8000-000000000002','Clásicos Mexicanos','Comforting classics, bright salsas, and generous plates.',2,true),
('20000000-0000-4000-8000-000000000104','20000000-0000-4000-8000-000000000002','Sides & Refreshers','Something crunchy. Something cool.',4,true),
('20000000-0000-4000-8000-000000000105','20000000-0000-4000-8000-000000000002','Breakfast','A sunny start to the day, made fresh and served all morning.',3,true),
('20000000-0000-4000-8000-000000000106','20000000-0000-4000-8000-000000000002','Sweet Finish','Save a little room for cinnamon and sugar.',5,true);
