('20000000-0000-4000-8000-000000000201','20000000-0000-4000-8000-000000000001','Street Taco','One warm taco with your choice of filling, onion, cilantro and salsa.',350,true,'menu-man-public-showcase','carne-asada-taco',false,'/img/super-tacos/approved/carne-asada-tacos.webp','/img/super-tacos/approved/carne-asada-tacos.webp',null),
('20000000-0000-4000-8000-000000000204','20000000-0000-4000-8000-000000000001','Super Burrito','Grilled steak, rice, cheese, pico de gallo, and crema wrapped in a warm flour tortilla.',1295,true,'menu-man-public-showcase','california-burrito',false,'/img/super-tacos/approved/burrito.webp','/img/super-tacos/approved/burrito.webp',null),
('20000000-0000-4000-8000-000000000205','20000000-0000-4000-8000-000000000001','Burrito','Your choice of filling with rice, beans, cheese and roasted tomato salsa.',1095,true,'menu-man-public-showcase','chicken-burrito',false,'/img/super-tacos/approved/chicken-burrito.webp','/img/super-tacos/approved/chicken-burrito.webp',null),
('20000000-0000-4000-8000-000000000206','20000000-0000-4000-8000-000000000001','Black Bean Burrito','Slow-cooked black beans and melted cheese in a soft flour tortilla.',895,true,'menu-man-public-showcase','bean-cheese-burrito',false,'/img/super-tacos/approved/black-bean-burrito.webp','/img/super-tacos/approved/black-bean-burrito.webp',null),
('20000000-0000-4000-8000-000000000208','20000000-0000-4000-8000-000000000001','Loaded Nachos','Tortilla chips with beans, cheese, guacamole, pico and your choice of topping.',945,true,'menu-man-public-showcase','loaded-nachos',false,'/img/super-tacos/approved/loaded-nachos.webp','/img/super-tacos/approved/loaded-nachos.webp',null),
