\set ON_ERROR_STOP on
-- Direct Production connection only. No pooler host is inferred or accepted.
-- Run via the read-only wrapper for preflight/verification with pinned trust.
\getenv release_sslmode PGSSLMODE
\getenv release_rootcert PGSSLROOTCERT
\getenv release_appdata APPDATA
begin isolation level serializable read write;
set local lock_timeout='2s';
set local statement_timeout='30s';
select set_config('menu_man.release_host', :'HOST', true);
select set_config('menu_man.release_user', :'USER', true);
select set_config('menu_man.release_port', :'PORT', true);
select set_config('menu_man.release_project', :'production_project_ref', true);
select set_config('menu_man.release_sslmode', :'release_sslmode', true);
select set_config('menu_man.release_rootcert', :'release_rootcert', true);
select set_config('menu_man.release_appdata', :'release_appdata', true);
do $$ begin
  if current_setting('menu_man.release_project') <> 'fullaiodvmilkdxyxnln'
    or current_setting('menu_man.release_host') <> 'db.fullaiodvmilkdxyxnln.supabase.co'
    or current_setting('menu_man.release_user') <> 'postgres'
    or current_setting('menu_man.release_port') <> '5432'
    or current_database() <> 'postgres' or current_user <> 'postgres'
    or current_setting('menu_man.release_sslmode') <> 'verify-full'
    or btrim(current_setting('menu_man.release_rootcert')) = ''
    or replace(lower(current_setting('menu_man.release_rootcert')),chr(92),'/') <> replace(lower(current_setting('menu_man.release_appdata')),chr(92),'/') || '/postgresql/root.crt'
    or not coalesce((select ssl from pg_stat_ssl where pid=pg_backend_pid()),false)
  then raise exception 'Exact Production identity and verified TLS required'; end if;
end $$;

-- Separate future Production approval, verified database backup and fresh
-- read-only preflight are prerequisites. This package has no execution wrapper.
select set_config('menu_man.release_approval', :'approve_public_content', true);
select set_config('menu_man.backup_sha', :'production_backup_sha256', true);
select set_config('menu_man.baseline_at', :'baseline_captured_at', true);
do $$ begin
  if current_setting('menu_man.release_approval') <> 'publish-super-tacos-browse-only'
    or current_setting('menu_man.backup_sha') !~ '^[a-f0-9]{64}$'
    or current_setting('menu_man.baseline_at')::timestamptz < now()-interval '30 minutes'
    or current_setting('menu_man.baseline_at')::timestamptz > now()
  then raise exception 'Separate approval, verified backup SHA and fresh baseline required'; end if;
  perform pg_advisory_xact_lock(20000000, 300);
end $$;
do $$ declare t text; collision boolean; v_entry record; v_column text; begin
  for v_entry in select key,value from jsonb_each($schema${"restaurants":["id","slug","name","tagline","description","logo_url","hero_image_url","phone","address_line1","city","state","postal_code","timezone","theme_preset","currency","is_active","is_indexable","theme_overrides","primary_domain","pickup_url","doordash_url","google_maps_url","instagram_url","facebook_url","latitude","longitude"],"menus":["id","restaurant_id","name","is_published"],"menu_sections":["id","menu_id","name","description","sort_order","is_active"],"menu_items":["id","restaurant_id","name","description","price_cents","is_active","source_system","source_item_id","is_orderable","image_url","source_image_url","image_path"],"menu_section_items":["section_id","item_id","sort_order"],"modifier_groups":["id","restaurant_id","name","is_active"],"modifier_options":["id","restaurant_id","modifier_group_id","name","default_price_adjustment_cents","sort_order","is_active","is_default"],"menu_item_modifier_groups":["restaurant_id","menu_item_id","modifier_group_id","min_selections","max_selections","sort_order","is_active"],"restaurant_business_hours":["restaurant_id","day_of_week","open_time","close_time","is_closed","sort_order"],"restaurant_ordering_settings":["restaurant_id","pickup_enabled","asap_enabled","scheduled_pickup_enabled","tax_strategy","tax_rate_basis_points"]}$schema$::jsonb) loop
    for v_column in select value from jsonb_array_elements_text(v_entry.value) loop
      if not exists(select 1 from information_schema.columns col where col.table_schema='public' and col.table_name=v_entry.key and col.column_name=v_column)
      then raise exception 'Required column missing: %.%',v_entry.key,v_column; end if;
    end loop;
  end loop;
  if (select array_agg(c.relname::text order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and c.relkind in ('r','p')) is distinct from array['menu_item_modifier_groups','menu_item_modifier_option_overrides','menu_items','menu_section_items','menu_sections','menus','modifier_groups','modifier_options','order_item_modifiers','order_items','orders','restaurant_business_hours','restaurant_order_counters','restaurant_ordering_settings','restaurants']
  then raise exception 'Production 15-table schema changed; stop for review'; end if;
  if not exists(select 1 from information_schema.columns col where col.table_schema='public'
      and col.table_name='restaurants' and col.column_name='is_indexable' and col.data_type='boolean' and col.is_nullable='NO')
  then raise exception 'Production indexability migration missing or incompatible'; end if;
  if not exists(select 1 from pg_constraint con where con.conrelid='public.menu_section_items'::regclass
      and con.contype='p' and pg_get_constraintdef(con.oid)='PRIMARY KEY (section_id, item_id)')
  then raise exception 'Production composite menu placement key missing'; end if;
  if exists(select 1 from public.restaurants where lower(slug)='super-tacos' or id='20000000-0000-4000-8000-000000000001'::uuid)
  then raise exception 'Existing restaurant: stop; never adopt, overwrite or rerun'; end if;
  foreach t in array array['restaurants','menus','menu_sections','menu_items','modifier_groups','modifier_options'] loop
    execute format('select exists(select 1 from public.%I where id::text like ''20000000-0000-4000-8000-%%'')',t) into collision;
    if collision then raise exception 'Reserved identity collision in %',t; end if;
  end loop;
end $$;
select set_config('menu_man.baseline_content', :'baseline_content_sha', true);
select set_config('menu_man.baseline_protected', :'baseline_protected_sha', true);
do $$ begin
  if current_setting('menu_man.baseline_content') <> encode(sha256(convert_to(concat_ws('|',(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurants a where not (id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menus a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_sections a where not (menu_id='20000000-0000-4000-8000-000000000002'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_items a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_section_items a where not (section_id in (select id from public.menu_sections where menu_id='20000000-0000-4000-8000-000000000002'::uuid) or item_id in (select id from public.menu_items where restaurant_id='20000000-0000-4000-8000-000000000001'::uuid))),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.modifier_groups a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.modifier_options a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_item_modifier_groups a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_business_hours a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid)),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_ordering_settings a where not (restaurant_id='20000000-0000-4000-8000-000000000001'::uuid))),'UTF8')),'hex')
    or current_setting('menu_man.baseline_protected') <> encode(sha256(convert_to(concat_ws('|',(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.menu_item_modifier_option_overrides a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.orders a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.order_items a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.order_item_modifiers a where true),(select encode(sha256(convert_to(coalesce(string_agg(encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex'),'' order by encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')),''),'UTF8')),'hex') from public.restaurant_order_counters a where true)),'UTF8')),'hex')
  then raise exception 'Other-tenant content or operational fingerprint changed; rollback/stop'; end if;
end $$;
